// The base returns a value from end(); the override returns nothing. A discarded call (an
// expression statement) dispatches over the differing returns: nothing reads the value.
class Base {
  constructor(id) { this.id = id; this.log = []; }
  end(cb) { this.log.push("base:" + this.id); return { quit: this.id }; }
  close() { this.end(); return this.log.join(","); }
}
class Pool extends Base {
  end(cb) { this.log.push("pool:" + typeof cb); if (typeof cb === "function") cb(); }
}
/** @returns {Base} */
function make(i) {
  return i === 0 ? new Base(0) : new Pool(i);
}
module.exports = { Base, Pool, make };
